"""Install full-text v2.3 Collection cards for backfill batch 032."""
from __future__ import annotations
import json
from pathlib import Path
from install_full_collection_batch_014 import figure, provenance, sec

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "collection_cards"

def card(pid: str, source_version: str, source_pdf: str, title: str, title_zh: str,
         profile: str, record: str, topic: str, metadata: dict[str, object],
         sections: list[dict[str, object]], figfile: str, figlabel: str, figpage: int,
         figtype: str, alt: str, caption: str, rationale: str,
         equations: list[dict[str, object]], evidence: list[str]) -> dict[str, object]:
    return {"arxiv_id": pid, "source_version": source_version, "source_pdf": source_pdf,
            "title_en": title, "title_zh": title_zh, "curation_status": "full_text_verified",
            "card_standard_version": "2.3", "paper_profile": profile,
            "style_reference": "physicist_daily_arxiv", "provenance": provenance([record], [topic]),
            "verified_metadata": metadata, "sections": sections,
            "cover": {"mode": "source_figure", "asset_path": f"assets/collection-figures/{pid}/{figfile}",
                      "label": figlabel, "visual_type": figtype, "evidence": f"paper.pdf p. {figpage}, {figlabel}",
                      "alt_text": alt, "caption": caption, "selection_rationale": rationale},
            "figure_refs": [figure(pid, figfile, figlabel, figpage, "support the central result", alt, caption,
                                   "The figure supports the stated protocol-specific claim, not an unrestricted generalization.")],
            "equation_refs": equations, "evidence_refs": evidence}

