def main() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    ids=[]
    for item in CARDS:
        pid=str(item["arxiv_id"]); (OUT/f"{pid}.json").write_text(json.dumps(item,ensure_ascii=False,indent=2)+"\n",encoding="utf-8"); ids.append(pid)
    print(json.dumps({"installed":ids},ensure_ascii=False)); return 0
if __name__ == "__main__": raise SystemExit(main())
